window.COURSES = [
 {id:1,week:1,track:'共通',title:'把自己介绍清楚',en:'Start with your story',desc:'用统计学背景与真实经历，建立60—90秒的求职介绍。',goal:'能说清背景、目标岗位、个人贡献和业务价值。',focus:'不要背整篇稿。先列4个英文关键词，再连成自己的句子。',framework:'Background → Role → Evidence → Value',phrases:[['My academic background is in statistics.','交代统计学背景。'],['My responsibility was to …','界定自己真实承担的部分。'],['I would like to apply these skills to …','把已有能力连接到目标工作。']],sample:'My academic background is in statistics, and I am interested in project management and data analysis in manufacturing. I enjoy turning information into clear actions. In one experience I would like to discuss, my responsibility was [your actual responsibility]. I used [your actual method] to produce [a verified deliverable]. This experience helped me understand the importance of clear definitions, reliable information and timely communication.',translation:'先说明背景与方向，再用一项真实任务证明能力。方括号必须换成自己能核实的内容；没有可靠结果数字时，用具体交付物。',speaking:'录一段60—90秒自我介绍。至少包含一项真实任务，并回答：What exactly did you do?',writing:'写80—100词给新同事的介绍邮件：你的角色、能支持的事项、希望了解的工作。',steps:['先看B1口语的 Meeting face-to-face，提取3个自然表达。','用4个英文关键词录首版，不写完整中文稿。','删去无法用实例支持的形容词，再录一次。'],checks:['说清目标岗位','有真实个人动作','不照稿完成60秒'],resources:['speaking','level'],questions:[{q:'面试中说明个人贡献，哪句最合适？',options:['I was responsible for updating the tracking list.','I am excellent at everything.','Our whole company succeeded because of me.'],a:0,why:'具体动作和范围比空泛评价更容易追问和自证。'},{q:'没有可靠的量化业绩时，应怎样处理？',options:['补一个看起来合理的百分比','说明实际完成的交付物与验证方式','只说团队很成功'],a:1,why:'可核实的具体交付物能支持经历，不应编造数字。'}]},
 {id:2,week:2,track:'共通',title:'让经历经得起追问',en:'Interview with evidence',desc:'准备项目与分析故事，练个人贡献、困难、结果和反思。',goal:'讲清2段真实经历，并连续回答3个追问。',focus:'故事中的团队目标和个人动作要分开；先回答问题，再补背景。',framework:'Context → Task → Your action → Result → Learning',phrases:[['The main challenge was …','先点出具体困难。'],['I checked … before deciding to …','交代判断依据。'],['One thing I would improve is …','说明可执行的反思。']],sample:'The main challenge was that different colleagues used different definitions for the same status. My task was to [actual task]. I first checked the source information, then [actual action]. The output was [verified deliverable]. I would improve the process by agreeing on definitions earlier and confirming who owns each update.',translation:'这是带占位符的练习骨架。用你的真实经历替换任务、动作和产出，不把整个团队结果都归因于自己。',speaking:'用90秒讲一段真实项目或分析经历。伙伴追问：Why did you choose that method? What was your personal contribution? What would you do differently?',writing:'给面试联系人写一封80—120词跟进邮件，感谢交流、重申岗位兴趣、询问下一步安排。',steps:['先列事实，不先追求高级词汇。','把同一故事压缩成30秒与90秒两个版本。','抽一个没准备过的追问，先直接作答。'],checks:['动作与结果对应','个人和团队边界清楚','能回答一个陌生追问'],resources:['speaking','writing'],questions:[{q:'面对“What exactly did you do?”，最有效的回答起点是？',options:['重复公司背景','说明自己执行的一项动作','列出所有团队成员'],a:1,why:'问题要求个人贡献，应直接说明自己的动作，再补证据。'},{q:'复盘经历时，哪种反思更可执行？',options:['I will work harder.','Everything was perfect.','I would agree on metric definitions before collecting data.'],a:2,why:'具体改进动作比泛泛态度更能说明反思。'}]},
 {id:3,week:3,track:'项目管理',title:'做一次有行动的项目周报',en:'Updates that move work forward',desc:'把里程碑、风险、影响和请求组织成两分钟汇报。',goal:'让听者知道项目在哪里、风险是什么、接下来谁做什么。',focus:'on track、at risk、overdue分别表示按计划、有风险、已经逾期。',framework:'Status → Risk → Impact → Action → Request',phrases:[['The milestone is at risk because …','说明里程碑风险及依据。'],['Alex will confirm the date by …','写清责任人与时点。'],['We need a decision on …','把讨论转成具体决策请求。']],sample:'The sample build is progressing, but the validation milestone is at risk. A required component is expected two days later than planned. We are checking whether current inventory can cover the build, so the impact on customer delivery is not yet confirmed. Alex will confirm the earliest available date by 14:00 China Standard Time tomorrow. We need the project manager to help resolve the testing-resource conflict.',translation:'这是虚构项目更新。已知的到货变化与未确认的客户影响分开，结尾说明需要的支持。',speaking:'模拟一个样件延期问题，做2分钟更新。伙伴追问：What is confirmed? Who owns the next action? When will we know more?',writing:'写一份5行项目周报，包含status、risk、impact、action owner、due date。',steps:['听一段业务材料，抓住责任人、日期和待确认事项。','用框架讲首版，再把模糊的soon改成具体时点。','整理3条英文行动项。'],checks:['区分风险与已发生问题','写明owner和due date','明确一个请求'],resources:['listening','emails'],questions:[{q:'尚未延期，但可能赶不上里程碑，应说？',options:['The milestone is closed.','The milestone is at risk.','The milestone is overdue.'],a:1,why:'at risk表示有风险；overdue表示期限已过。'},{q:'哪条行动项最清楚？',options:['Someone should check soon.','Please follow up.','Alex will confirm the delivery date by 14:00 UTC+8 on 13 November.'],a:2,why:'包含动作、责任人、具体日期、时间与时区。'}]},
 {id:4,week:4,track:'共通',title:'写清一封邮件，跟完一件事',en:'Write for a clear next step',desc:'练请求、催办、延期、升级与会议跟进。',goal:'在12分钟左右写清事实、请求、期限与下一步。',focus:'邮件开头交代目的；收件人应能立即判断要做什么。',framework:'Purpose → Context → Request → Deadline → Follow-up',phrases:[['Could you please confirm … by …?','提出具体且有期限的请求。'],['The impact is still being assessed.','标明影响仍在核查。'],['I will send an update by …','约定下一次沟通。']],sample:'Subject: Confirmation needed: component delivery\n\nHi Alex,\nThe supplier has reported a two-day delay for 200 components. Could you please confirm the earliest available delivery date and whether a partial shipment is possible by 14:00 China Standard Time on 13 November? Production Planning is checking inventory coverage. The impact on customer delivery has not yet been confirmed. I will consolidate the updates and share the next status with the project manager.\n\nBest regards,\nLu Kun',translation:'模拟邮件先交代变化，再提出明确请求。未核实的交期影响不写成承诺。',speaking:'用30秒口头说明这封邮件的目的，再模拟同事只回复“soon”，追问其具体日期和确认程度。',writing:'写120—160词请求邮件，然后让伙伴给出新信息，继续写一封回复和一封经理更新。',steps:['学English for emails的Enquiries和Organising your writing。','独立写首稿，检查数量、日期、权限与行动。','到W4末按测试中心完成第一次复测。'],checks:['主题说明事项','请求有期限','已知与未知分开'],resources:['emails','writing'],questions:[{q:'供应商只说“should arrive soon”，你应？',options:['向客户保证交付','核实具体日期、数量和确认程度','当作已经到货'],a:1,why:'soon和should都不能代替确认的数量、日期。'},{q:'会议纪要最应包含哪一组？',options:['Action, owner, due date, open issue','Only the meeting title','All the small talk'],a:0,why:'行动、责任人、期限和未决事项支持后续推进。'}]},
 {id:5,week:5,track:'数据分析',title:'把数字讲成业务结论',en:'From numbers to meaning',desc:'练产量、质量和交付指标，准确表达变化幅度。',goal:'做2分钟数据说明，数字、分母、单位和时间窗口准确。',focus:'3%升到4%是上升1个百分点；相对增幅约33.3%。',framework:'Finding → Evidence → Interpretation → Next step',phrases:[['We achieved 90% of the production plan.','说明计划完成率。'],['The rate rose by one percentage point.','准确表达百分点变化。'],['The cause has not yet been established.','区分观察与原因判断。']],sample:'We produced 900 units against a plan of 1,000, achieving 90% of the plan. Of the 900 units produced, 36 were defective, so the defect rate was 4%. This was one percentage point higher than the previous week. On-time delivery fell from 92% to 88%. We should check product mix, production lines and reporting consistency before drawing conclusions about the causes.',translation:'所有数据为模拟。先报结论与数字，再提出核查方向；不能仅凭同时变化就认定因果。',speaking:'用90秒汇报模拟数据：计划1000、产出900、缺陷36、上期缺陷率3%、交付及时率92%到88%。',writing:'写100—130词给经理的分析摘要，包含结论、证据、未确定的因素和下一步。',steps:['口头读出百分比、百分点和日期。','用同一数据分别做30秒和90秒说明。','把数据换成计划1500、产出1200、缺陷24，重新计算。'],checks:['缺陷率分母正确','区分百分比和百分点','未把相关性说成因果'],resources:['listening','writing'],questions:[{q:'缺陷率由3%到4%，变化是？',options:['上升1%','上升1个百分点','下降1个百分点'],a:1,why:'百分点变化是4%-3%=1个百分点，相对增幅约33.3%。'},{q:'产出900件，其中36件缺陷，缺陷率是？',options:['3.6%','90%','4%'],a:2,why:'分母是实际产出的900件，36/900=4%。'}]},
 {id:6,week:6,track:'数据分析',title:'先对齐口径，再解释差异',en:'Ask better data questions',desc:'处理报表不一致、缺失、重复与刷新延迟。',goal:'能向业务方提出5个有用的核实问题，并写数据请求。',focus:'先检查定义、时间、范围和分母，再讨论谁的结果正确。',framework:'Definition → Scope → Grain → Time → Quality',phrases:[['Does this include cancelled orders?','核查统计范围。'],['What is the denominator for this rate?','核查分母。'],['When was the dataset last refreshed?','核查刷新时点。']],sample:'Before comparing the two dashboards, I would like to confirm the definitions. Does your spreadsheet include only completed orders, or all orders? Are both reports using the same reporting period and time zone? We should also check the order-level grain, duplicate records and refresh time. Once the definitions are aligned, we can identify any remaining difference.',translation:'先把可能导致差异的口径问题明确，再对齐条件比较。不要直接说“你的表错了”。',speaking:'伙伴说：Your dashboard does not match my spreadsheet. 用英语提5个问题，核查指标定义、筛选、粒度和刷新时间。',writing:'写120词数据请求邮件，说明需要哪些字段、时间范围、粒度、用途和回复期限。',steps:['把一个常用指标用简单英文解释。','模拟业务方每次只补充一个条件，持续澄清。','写出数据来源和口径确认清单。'],checks:['问到时间窗口','问到分母和粒度','请求内容可以执行'],resources:['podcast','writing'],questions:[{q:'两个报表一个只含已完成订单，一个含全部订单，首先应？',options:['立即认定绩效下降','对齐分母和筛选范围','取两个比例的平均数'],a:1,why:'分母和范围不同的比例不能直接作为绩效变化比较。'},{q:'哪句最适合核实数据刷新时间？',options:['When was the dataset last refreshed?','Why are you always wrong?','Can you make it look better?'],a:0,why:'明确询问刷新时点，能检验数据是否存在时间差。'}]},
 {id:7,week:7,track:'项目管理',title:'处理供应与验证的冲突',en:'Coordinate under constraints',desc:'练物料短缺、供应商延期、验证排期和风险升级。',goal:'能说明约束、比较方案、请求批准并确认跟进。',focus:'建议、预计、确认和批准是不同状态，要在英语里说清。',framework:'Constraint → Options → Trade-offs → Approval → Follow-up',phrases:[['One option is a partial shipment.','提出备选方案。'],['This would require approval from …','说明审批依赖。'],['Could we confirm inventory coverage first?','先核查关键条件。']],sample:'The supplier can offer a partial shipment of 80 units, but the remaining 120 units are not yet confirmed. One option is to use current inventory for the initial build. Another is to request expedited shipping, subject to a quotation and approval. Before committing to either option, we need Production Planning to check coverage and Procurement to confirm the supplier schedule.',translation:'模拟案例里，80件方案、120件未知、加急待报价与审批分别标明；不越权替其他部门承诺。',speaking:'做10分钟角色对话：你是PM支持，伙伴交替扮演采购、测试和经理。要处理一次优先级冲突。',writing:'给经理写风险升级邮件：事实、可能影响、两个方案、待确认信息、需决策事项、下次更新。',steps:['用简单句解释lead time、inventory、validation。','用两个选项讨论时间、成本和质量权衡。','结束时复述owner、due date与审批事项。'],checks:['说清主要约束','区分方案与批准','以明确行动结束'],resources:['podcast','emails'],questions:[{q:'加急运输尚未获批，应该说？',options:['Expedited shipping has been approved.','We can consider expedited shipping, subject to approval.','The customer has agreed to pay.'],a:1,why:'subject to approval说明执行仍依赖批准。'},{q:'供应商晚到两天，客户是否一定晚交两天？',options:['不一定，要核查库存、排产等条件','一定','只要语气肯定就可以承诺'],a:0,why:'供应到货变化与客户交期影响之间仍有库存和计划等因素。'}]},
 {id:8,week:8,track:'共通',title:'从讨论到书面闭环',en:'Run a complete work cycle',desc:'读简报、做汇报、处理追问，再发送跟进纪要。',goal:'独立完成一次10分钟讨论和配套书面总结。',focus:'决策、建议、待确认事项分开；没有责任人的行动不算完整。',framework:'Brief → Update → Questions → Decisions → Written follow-up',phrases:[['Let me summarise what we have agreed.','复述已确认的决定。'],['This point remains open.','标记未决事项。'],['Please let me know if I have missed anything.','邀请纠正纪要。']],sample:'Thanks for the discussion. We agreed that Procurement will confirm the partial-shipment schedule, while Production Planning will check inventory coverage. The decision on expedited shipping remains open until we receive the quotation. I will update the action list and share the next status by the agreed time. Please let me know if I have missed anything.',translation:'用简洁总结把会议内容变成可执行的行动，未批准的加急决策保留为open。',speaking:'读一份新的业务简报，用3分钟汇报，再回答3个未知追问，最后用30秒确认行动。',writing:'写一份含decision、action、owner、due date、open issue的会议跟进。',steps:['请伙伴临时改变一个业务条件。','先澄清，再提出更新后的行动。','完成W8综合复测，决定后4周主攻岗位。'],checks:['回应了新条件','纪要与口头约定一致','未决事项有跟进'],resources:['listening','emails'],questions:[{q:'会议上提出但尚未批准的方案，应记录为？',options:['Approved decision','Completed task','Open proposal / pending approval'],a:2,why:'纪要应保留状态，避免把提议写成已决定。'},{q:'结束会议最有助于推进工作的是？',options:['复述行动、责任人和期限','只说Thanks','把所有背景再讲一次'],a:0,why:'行动确认能减少理解差异，支持会后跟进。'}]},
 {id:9,week:9,track:'共通',title:'读懂一篇制造业案例',en:'Read the business behind the words',desc:'用真实行业材料积累流程、质量和协作表达。',goal:'读250—500词，用90秒复述问题、行动和证据。',focus:'案例中的厂商观点、企业自述与独立证据要区分。',framework:'Problem → Action → Result → Evidence → Question',phrases:[['The company aimed to improve …','说明企业目标。'],['According to the case study, …','明确归因来源。'],['The article does not explain how … was measured.','指出尚不明确的测量信息。']],sample:'According to the case study, the company wanted to improve quality management and transparency. The approach involved connecting existing systems and standardising processes. When explaining the reported results, I would separate the supplier’s claims from independently verified evidence. I would also ask how the improvements were measured and over what period.',translation:'这是案例阅读的表达骨架，不是对任意企业成果的独立验证。引用数字时保留出处和测量条件。',speaking:'选NAF案例的一小段，90秒复述，再提出2个与业务或指标定义有关的问题。',writing:'写100词案例卡：业务问题、采取动作、报告结果、证据来源、你的问题。',steps:['先读Challenges、Keys to success、Results。','不逐词翻译，只选5个能复用的表达。','脱离原文复述，再核对是否扩大了结论。'],checks:['有来源归因','解释一个业务问题','提出一个证据问题'],resources:['cases','naf'],questions:[{q:'复述厂商案例中的成果时，更合适的是？',options:['According to the case study, the company reported …','I independently proved …','Every factory will achieve the same result.'],a:0,why:'保留来源归因，避免把自述扩大成独立验证或普遍保证。'},{q:'读完行业文章后，最能检查理解的是？',options:['复制全部原文','不看原文复述问题、动作和结果','只统计生词数量'],a:1,why:'脱稿复述可以检验是否理解业务逻辑。'}]},
 {id:10,week:10,track:'共通',title:'提出建议，也能礼貌异议',en:'Disagree with a useful alternative',desc:'项目岗练资源协商，分析岗练证据讨论。',goal:'说明顾虑、给出依据和替代方案，并推进决策。',focus:'反对意见要连接事实与可执行选择。',framework:'Acknowledge → Concern → Evidence → Alternative → Decision',phrases:[['I see your point. My concern is …','先回应对方，再提出具体顾虑。'],['Could we consider … instead?','提出替代方案。'],['What would we need to confirm before deciding?','推动确认决策条件。']],sample:'I see the benefit of bringing the date forward. My concern is that validation would not be complete by then. Could we keep the original validation window and prioritise the first shipment instead? We would need confirmation from Testing and Production Planning before committing to the revised plan.',translation:'先回应提前交付的价值，再说明验证限制并提出替代方案，最后明确需要确认的部门。',speaking:'PM方向讨论两个任务争用资源；DA方向讨论经理想把相关性解释成原因。每轮提出一个可执行替代方案。',writing:'写100—150词建议，包含支持建议的事实、一个权衡、一个需要确认的条件。',steps:['从B1口语Agreeing and disagreeing提取表达。','用同一观点练直接版和更礼貌版。','让伙伴挑战你的证据，再调整建议。'],checks:['顾虑有依据','提供替代方案','能回应质疑'],resources:['speaking','podcast'],questions:[{q:'哪种异议更有助于协作？',options:['You are wrong.','I see the benefit. My concern is the validation timeline. Could we check another option?','That is impossible, goodbye.'],a:1,why:'回应目标、说明顾虑并给出下一步，可以推进讨论。'},{q:'同时发生的两个指标变化能直接证明因果吗？',options:['能','只要变化方向相同就能','不能，还需排查其他解释和验证'],a:2,why:'同时变化只是观察，因果判断需要进一步证据。'}]},
 {id:11,week:11,track:'共通',title:'对准你的下一场面试',en:'Prepare for the actual role',desc:'用具体JD、公司业务与真实故事做岗位化准备。',goal:'完成20分钟模拟面试和一份限时书面任务。',focus:'每个岗位要求对应一条真实证据，未做过的内容说明如何迁移与学习。',framework:'Requirement → Evidence → Contribution → Transfer',phrases:[['A relevant example from my experience is …','以经历回应岗位要求。'],['I have not owned that process, but I have supported …','准确说明经验范围。'],['How is success measured in this role?','询问岗位成功标准。']],sample:'A relevant example from my experience is [real example]. My role was [actual scope], and I contributed by [specific action]. This is relevant to the position because [connection to the job]. I would also like to understand how the team measures success and how this role works with Production, Quality and Procurement.',translation:'用岗位要求与自身证据建立连接。面试反问围绕目标、协作和衡量方式。',speaking:'选一份真实JD，用3条要求匹配3条经历；接受英文追问，不临时编造未做过的工作。',writing:'限时写一封岗位相关邮件或分析摘要，写完解释自己为何这样组织信息。',steps:['从JD提取3项核心任务。','为每项任务准备一个事实与一项可迁移能力。','模拟面试后只修3个关键问题，再抽新题。'],checks:['回答对应岗位任务','例子可自证','反问具体'],resources:['speaking','writing'],questions:[{q:'JD要求的流程你没有独立负责过，应该？',options:['声称已经独立主导','准确说明相关支持经验和迁移方法','绕过问题完全不回答'],a:1,why:'经验范围准确，同时说明相关能力与学习路径。'},{q:'哪句更适合岗位面试反问？',options:['How is success measured in this role?','What does your company do?（完全未准备时）','Can I avoid all meetings?'],a:0,why:'询问成功标准能帮助了解具体任务与评价方式。'}]},
 {id:12,week:12,track:'共通',title:'把英语用进完整工作流',en:'Make it work end to end',desc:'综合听读、汇报、讨论、邮件与复盘。',goal:'在陌生情境里独立完成沟通闭环，并确定下一阶段短板。',focus:'比较首测与末测的同类任务，既看分数，也看遗漏、用时和独立程度。',framework:'Understand → Clarify → Explain → Agree → Follow up',phrases:[['Here is what we know so far.','总结当前确认的事实。'],['The remaining uncertainty is …','指出未决信息。'],['The next action is …, owned by …, due by …','明确闭环行动。']],sample:'Here is what we know so far: production is below plan, but the defect rate has improved. We have not established a link between the supply issue and the quality change. The remaining uncertainty is inventory coverage. The next action is for Production Planning to confirm coverage, after which the project manager can review the delivery options and required approvals.',translation:'虚构综合场景中，质量改善和产量不足可以同时成立。保持不同指标与原因判断的边界。',speaking:'用一份新简报做3分钟更新，处理3个追问，并在会后口头复述行动。',writing:'发出120—160词跟进邮件：已知、未知、决定、责任人、期限、下一次更新。',steps:['按测试中心做W12陌生任务复测。','保留首次输出，不用修改稿替代成绩。','对照五项能力，为下月只选一个主攻短板。'],checks:['陌生题能独立完成','数字与承诺准确','留下明确跟进行动'],resources:['listening','writing','cases'],questions:[{q:'判断进步最可靠的做法是？',options:['只比较打卡天数','只看修改后范文','用陌生同类任务比较用时、准确性和独立程度'],a:2,why:'陌生任务能更好检查迁移能力，修改稿不能替代独立表现。'},{q:'只有文字答案，可以自动给发音满分吗？',options:['可以，句子正确就行','不可以，需要实际音频证据','可以按词数判断'],a:1,why:'文字无法提供发音与真实口语流畅度证据。'}]}
];
window.DOCS = [
 ['学习路线与逐周安排','01_学习路线.md'],['起点测试与阶段复测','02_起点测试与复测.md'],['评分标准与参考答案','03_评分标准与答案_测试后再看.md'],['日常练习包与陪练提示词','04_日常练习包.md'],['开源项目调研与选型','05_开源项目参考.md'],['12模块课程手册','06_模块课程手册.md']
];
